{
  "missing_information": [
    {
      "category": "system",
      "gap": "No systems or platforms are identified for discovering activities (e.g., community portals, provider websites, apps)",
      "why_it_matters": "Knowing which systems are used determines where automation can scrape, integrate, or receive notifications about available activities"
    },
    {
      "category": "decision",
      "gap": "The criteria for deciding whether an activity 'fits' are not defined (cost, location, time slot, age range, sibling conflicts, etc.)",
      "why_it_matters": "Automating or semi-automating the fit-check requires knowing which parameters to evaluate and in what priority order"
    },
    {
      "category": "actor",
      "gap": "It is unclear who performs each step — one parent, both parents jointly, or a shared family account",
      "why_it_matters": "Multi-actor workflows require coordination logic and may involve approval steps before enrollment or calendar changes are confirmed"
    },
    {
      "category": "integration_constraint",
      "gap": "The calendar system used (and whether it is shared across family members) is not specified",
      "why_it_matters": "Automating calendar updates depends on API availability and whether a single calendar or multiple linked calendars must be updated"
    },
    {
      "category": "exception",
      "gap": "No information is given about what happens when a schedule change conflicts with an existing commitment or makes the activity no longer viable",
      "why_it_matters": "Exception paths (cancel enrollment, find alternative, notify provider) are often the most labor-intensive and highest-value automation targets"
    },
    {
      "category": "frequency",
      "gap": "The frequency of enrollment cycles and schedule-change events is unknown (seasonal, monthly, ad hoc)",
      "why_it_matters": "Frequency drives the ROI calculation for automation and determines whether a standing integration or an on-demand trigger is more appropriate"
    },
    {
      "category": "input",
      "gap": "It is unclear how schedule-change notifications from providers are received (email, SMS, app push, phone call)",
      "why_it_matters": "The notification channel determines whether changes can be detected automatically or require manual monitoring and data entry"
    },
    {
      "category": "manual_effort",
      "gap": "The steps involved in the actual enrollment action are not described (online form, phone call, in-person, payment required)",
      "why_it_matters": "Understanding the enrollment mechanics reveals whether the sign-up step itself can be automated or only assisted"
    }
  ],
  "clarification_questions": [
    {
      "id": "Q1",
      "question": "What sources or platforms do you use to discover available activities for your child — for example, a specific community website, a provider app, email newsletters, or social media?",
      "targets": ["system"]
    },
    {
      "id": "Q2",
      "question": "What specific criteria do you evaluate to decide whether an activity is a good fit — such as cost, location, time slot, the child's age eligibility, or conflicts with other commitments?",
      "targets": ["decision"]
    },
    {
      "id": "Q3",
      "question": "How does the enrollment step actually work — do you complete an online form, make a phone call, pay a fee, or do something else, and does it require approval or agreement from another parent or guardian?",
      "targets": ["manual_effort", "actor"]
    },
    {
      "id": "Q4",
      "question": "Which calendar system do you use to track the activity schedule, and is it shared with other family members who also need to see or act on changes?",
      "targets": ["integration_constraint"]
    },
    {
      "id": "Q5",
      "question": "How do you typically receive notification of a schedule change from the activity provider — for example, via email, a text message, an app notification, or a phone call?",
      "targets": ["input"]
    },
    {
      "id": "Q6",
      "question": "When a provider's schedule change conflicts with an existing family commitment, what do you do — for example, do you cancel the enrollment, look for an alternative session, or contact the provider to negotiate?",
      "targets": ["exception"]
    }
  ]
}
